2	/**
3	 * files.ts — read, search and change files, under the names every agent already knows.
4	 *
5	 * ## Why this exists rather than `@modelcontextprotocol/server-filesystem`
6	 *
7	 * The official server has no line range and no content search. Measured across two runs
8	 * of this project's own agents, 202 tool calls: 37 of the 63 shell calls were
9	 * `sed -n A,Bp` and `grep -rn`, the agent rebuilding both by hand. The reviewer,
10	 * which has no shell, could not — it read one 1,700-line file four times with `head`
11	 * and `tail`, which never reach the middle, and 43% of everything it read came back
12	 * truncated.
13	 *
14	 * Candidates with the missing capabilities were evaluated by starting them and reading
15	 * their real schemas, because the documentation was wrong about the official one. None
16	 * was both mature and complete: the server that is official lacks the primitives, and
17	 * the ones that have them are single-author projects, one without a licence. Adopting
18	 * any would also have meant 14 to 17 tools where six will do, with names and truncation
19	 * messages belonging to somebody else.
20	 *
21	 * ## The names
22	 *
23	 * `read`, `grep`, `glob`, `edit`, `write`, `list` — what OpenCode and Claude Code call
24	 * them, which is what a model has seen most. They arrive unprefixed because this server
25	 * sets `unprefixed: true`; see `ToolDef::unprefixed` in the core for why two servers
26	 * cannot both claim a name and what happens when they try.
27	 *
28	 * ## The rule every result here follows
29	 *
30	 * A result that left something out says what to ask for to get the rest. A truncation
31	 * that stops mid-file with no next step is what produced four reads of one file: the
32	 * agent changed `head: 40` to `head: 760` because nothing told it that the number it
33	 * was changing does not decide how much comes back.
34	 */
35	import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync, existsSync } from "node:fs";
36	import { isAbsolute, resolve, relative, sep, dirname } from "node:path";
37	import { spawnSync } from "node:child_process";
38	import { buildMcpTools, defineMcpTool, serveMcpServer, z, type McpToolResult } from "../../../adapters/mcp/mcp-tool.ts";
39	import { TOOL_OUTPUT_BUDGET } from "../../../shared/tool-output.ts";
40	import { WORKSPACE_PATH } from "../../../domain/work/workspace.ts";
41	import { MAX_IMAGE_BYTES, sniffMimeType } from "../../../adapters/github/issue-images.ts";
42	import { hardenCredentialHolder } from "../lib/harden.ts";
43	
44	function log(message: string): void {
45	  console.error(`[atomaton-files] ${message}`);
46	}
47	
48	hardenCredentialHolder(log);
49	
50	/**
51	 * Where this server will look.
52	 *
53	 * The work tree, and the shared workspace. The official server was given the work tree
54	 * alone, so `/tmp/atomaton-workspace` was reachable from the shell and from nothing
55	 * else — while the prompt template told every agent it was "an ordinary directory, on
56	 * the same filesystem, at the same path for every tool". That sentence is true now.
57	 */
58	const ROOTS = [resolve(process.cwd()), WORKSPACE_PATH];
59	
60	/** Lines returned by one `read` when the caller does not say. */
61	const DEFAULT_READ_LINES = 400;
62	
63	/** Matching lines reported by one `grep` when the caller does not say. */
64	const DEFAULT_MAX_MATCHES = 60;
65	
66	/**
67	 * A path inside one of the roots, or an error naming what is allowed.
68	 *
69	 * Resolved before comparing, so `../` cannot walk out of the tree, and compared with a
70	 * separator appended so that `/tmp/atomaton-workspace-other` does not pass as the
71	 * workspace.
72	 */
73	function within(path: string): string {
74	  const full = isAbsolute(path) ? resolve(path) : resolve(process.cwd(), path);
75	  const inside = ROOTS.some(
76	    (root) => full === root || full.startsWith(root.endsWith(sep) ? root : root + sep),
77	  );
78	  if (!inside) {
79	    throw new Error(
80	      `'${path}' is outside the directories this tool can reach. They are: ${ROOTS.join(", ")}.`,
81	    );
82	  }
83	  return full;
84	}
85	
86	/** How a path is shown back: relative to the work tree when it is inside it. */
87	function shown(full: string): string {
88	  const rel = relative(process.cwd(), full);
89	  return rel && !rel.startsWith("..") ? rel.split(sep).join("/") : full;
90	}
