92	const READ_SCHEMA = z.object({
93	  path: z.string().describe("File to read. Relative to the working directory, or absolute."),
94	  offset: z
95	    .number()
96	    .int()
97	    .min(1)
98	    .optional()
99	    .describe(
100	      "First line to return, counting from 1. Default 1. To continue a read that stopped early, pass the offset its result named.",
101	    ),
102	  limit: z
103	    .number()
104	    .int()
105	    .min(1)
106	    .optional()
107	    .describe(
108	      `How many lines to return. Default ${DEFAULT_READ_LINES}. A larger number is clipped by the size budget, and the result says how far it actually got.`,
109	    ),
110	});
111	
112	/**
113	 * Lines of a file, numbered, and how to get the rest.
114	 *
115	 * Numbered because every error a compiler emits and every other tool here speaks in
116	 * line numbers, and a range asked for by line is unusable when what comes back is not.
117	 */
118	function readFile(a: z.infer<typeof READ_SCHEMA>): McpToolResult {
119	  const full = within(a.path);
120	  if (!existsSync(full)) throw new Error(`'${a.path}' does not exist.`);
121	  if (statSync(full).isDirectory()) throw new Error(`'${a.path}' is a directory. Use list.`);
122	
123	  // A picture comes back as a picture, which the server this replaces did through a
124	  // separate `read_media_file`. One tool rather than two, because the caller asking
125	  // for a screenshot is asking to read a file and should not have to know in advance
126	  // which kind it is. The type is sniffed from the bytes, not taken from the
127	  // extension: a file named `.png` holding something else is what a provider rejects.
128	  const bytes = new Uint8Array(readFileSync(full));
129	  const mimeType = sniffMimeType(bytes);
130	  if (mimeType) {
131	    const data = Buffer.from(bytes).toString("base64");
132	    if (data.length > MAX_IMAGE_BYTES) {
133	      throw new Error(`'${a.path}' is too large an image to include (${bytes.length} bytes).`);
134	    }
135	    log(`read ${shown(full)} as ${mimeType}, ${bytes.length}B`);
136	    return { text: `Image ${shown(full)} (${mimeType}).`, images: [{ type: "image", data, mimeType }] };
137	  }
138	
139	  const lines = readFileSync(full, "utf8").split("\n");
140	  // A trailing newline leaves one empty last element, which is not a line of the file.
141	  if (lines.length > 0 && lines[lines.length - 1] === "") lines.pop();
142	
143	  const total = lines.length;
144	  const from = a.offset ?? 1;
145	  if (total === 0) return { text: `${shown(full)} is empty.` };
146	  if (from > total) throw new Error(`'${a.path}' has ${total} lines; offset ${from} is past the end.`);
147	
148	  const wanted = Math.min(a.limit ?? DEFAULT_READ_LINES, total - from + 1);
149	  const out: string[] = [];
150	  let used = 0;
151	  for (let i = 0; i < wanted; i += 1) {
152	    const numbered = `${from + i}\t${lines[from + i - 1]}`;
153	    // The budget, rather than the line count, is usually what stops this. Both are
154	    // reported the same way, because to the caller they are the same event.
155	    if (used + numbered.length + 1 > TOOL_OUTPUT_BUDGET) break;
156	    out.push(numbered);
157	    used += numbered.length + 1;
158	  }
159	
160	  const last = from + out.length - 1;
161	  // The same-arguments clause is deliberate. The failure this marker meets -- #607, #627,
162	  // atoma#47, all verified against session transcripts -- is a caller repeating the call
163	  // unchanged because its reasoning believes it already passed the offset it meant to.

